/**
 * Retrieve file buffers from global context and attach them to entry.files.
 *
 * Files with a context_key were stored by Fetch files via
 * global.set("files.key", buffer). This node retrieves each buffer
 * and attaches it so POST to Rayvn log can perform the actual upload.
 *
 * Files without context_key (oversized/skipped) are left as-is —
 * POST to Rayvn log will detect and report them via _failed_files.
 */
const entry = msg.entry;
const files = entry.files || [];

entry.files = files.map(file => {
    if (!file.context_key) return file;

    const buffer = global.get("files." + file.context_key);

    if (!buffer || buffer.length === 0) {
        node.warn("No buffer found for context_key: " + file.context_key);
        return { ...file, buffer: null };
    }

    return { ...file, buffer };
});

return msg;

const entry  = msg.entry;
const source = entry.metadata.source;
const utils  = global.get("utils");

msg.metadata = entry.metadata;
msg.payload  = {
    content:        entry.text,
    callsign:       `${utils.build_callsign(source)} ${entry.author}`,
    isLocation:     false,
    replyMessageId: null,
    files:          []
};

return msg;

const entry  = msg.entry;
const source = entry.metadata.source;
const utils  = global.get("utils");

msg.metadata = entry.metadata;
msg.payload  = {
    text:             `${utils.build_callsign(source)} ${entry.author}: ${entry.text || ""}`,
    keyEvent:         false,
    releasedInfo:     false,
    loggedByFullName: `${utils.build_callsign(source)} ${entry.author}`,
    labels:           [],
    files:            entry.files || []
};

return msg;
